UPDATE community_comment
SET content    = #{request.content},
    updated_at = NOW()
WHERE comment_id = #{commentId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE community_comment
SET deleted_at = NOW()
WHERE comment_id = #{commentId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE community_comment
SET like_count = like_count + 1
WHERE comment_id = #{commentId}
